# Step: fetch all venmo social feed pages and filter yesterday transactions involving sibling emails

assert 'venmo_token' in globals() and venmo_token
assert 'sibling_email_set' in globals()

from datetime import datetime, timedelta

def parse_created_at(dt_str):
    if not dt_str:
        return None
    # try isoformat
    try:
        return datetime.fromisoformat(dt_str).date()
    except Exception:
        pass
    # try common formats
    for fmt in ['%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S', '%m/%d/%Y %H:%M:%S', '%a, %d %b %Y %H:%M:%S']:
        try:
            return datetime.strptime(dt_str, fmt).date()
        except Exception:
            continue
    return None

# yesterday_date from previous step
# ensure variable exists
if 'yesterday_date' not in globals():
    now_info = apis.phone.get_current_date_and_time()
    today_date = datetime.strptime(now_info['date'], '%A, %B %d, %Y').date()
    yesterday_date = today_date - timedelta(days=1)

print('yesterday_date:', yesterday_date)

page_index = 0
page_limit = 20
all_feed = []
while True:
    res = apis.venmo.show_social_feed(access_token=venmo_token, page_index=page_index, page_limit=page_limit)
    # API might return dict or list
    if isinstance(res, list):
        page_items = res
    elif isinstance(res, dict):
        page_items = res.get('transactions') or res.get('results') or res.get('feed') or []
    else:
        page_items = []
    print('page_index', page_index, 'items', len(page_items))
    if not page_items:
        break
    all_feed.extend(page_items)
    page_index += 1

print('total_feed_items:', len(all_feed))

# filter
matches = []
for tx in all_feed:
    tx_date = parse_created_at(tx.get('created_at'))
    if tx_date != yesterday_date:
        continue
    sender_email = (tx.get('sender') or {}).get('email')
    receiver_email = (tx.get('receiver') or {}).get('email')
    if (sender_email in sibling_email_set) or (receiver_email in sibling_email_set):
        matches.append(tx)

print('matched_transactions_count:', len(matches))
# print summary of matches
for tx in matches:
    print({
        'transaction_id': tx.get('transaction_id'),
        'created_at': tx.get('created_at'),
        'amount': tx.get('amount'),
        'sender_email': (tx.get('sender') or {}).get('email'),
        'receiver_email': (tx.get('receiver') or {}).get('email'),
        'like_count_before': tx.get('like_count')
    })

matches_ids = [tx.get('transaction_id') for tx in matches if tx.get('transaction_id') is not None]
print('matches_ids:', matches_ids)

